#!/usr/bin/env python3
from pathlib import Path
import collections, datetime, hashlib, html, importlib.util, json, re, shutil
R=Path(__file__).resolve().parent
body=(R/'sociu_body_ro.txt').read_text();flat=' '.join(body.split())
m=json.loads((R/'stylometry.json').read_text());r=json.loads((R/'pangram_web/segments_accessibility.json').read_text());episodes=json.loads((R/'pangram_web/episode_breakdown.json').read_text());v=json.loads((R/'rubric_validation.json').read_text())
# Map normalized segment offsets back to the untouched, paragraph-preserving input.
chars=[];mapping=[]
for match in re.finditer(r'\S+',body):
 if chars:chars.append(' ');mapping.append(match.start()-1)
 chars.extend(match.group());mapping.extend(range(match.start(),match.end()))
assert ''.join(chars)==flat
for s in r['segments']:
 s['start_original_char']=mapping[s['start_normalized_char']]
 s['end_original_char']=mapping[s['end_normalized_char']-1]+1
 s['label']=max(s['class_percentages_displayed'],key=s['class_percentages_displayed'].get)
 s['unicode_word_units']=len(re.findall(r'\w+',s['text']))
assert sum(s['unicode_word_units'] for s in r['segments'])==1753
assert sum(s['unicode_word_units'] for s in r['segments'] if s['label']=='AI')==1164
assert len(r['segments'])==24
websummary={k:val for k,val in r.items() if k!='segments'}
websummary.update({'source_input_sha256':hashlib.sha256(body.encode()).hexdigest(),'web_scan_time_displayed':'Nov 3, 2026 08:51 PM','client_timezone':'Asia/Hong_Kong','AI_labeled_segments':sum(s['label']=='AI' for s in r['segments']),'Human_labeled_segments':sum(s['label']=='Human' for s in r['segments']),'AI_assisted_labeled_segments':sum(s['label']=='AI-assisted' for s in r['segments']),'AI_labeled_unicode_word_units':1164,'total_unicode_word_units':1753,'raw_API_fraction_ai':None,'raw_API_fraction_ai_assisted':None,'raw_API_fraction_human':None,'API_attempt_outcome':'HTTP 402 Payment Required; no detector result, no resubmission. Successful readout obtained through user-requested web interface.','web_report_direct_url':None,'web_report_url_note':'Initial live route was /dashboard?prefill=true; it is not a persistent report identifier. Do not publish it as a permanent report link.','confidence_interpretation':'Displayed class percentages and confidence labels are provider outputs; they are not verified authorship probabilities.','local_section_rates':'Derived from existing full-document segment labels, not independent scans.'})
(R/'pangram_web/result_summary.json').write_text(json.dumps(websummary,ensure_ascii=False,indent=2)+'\n')
(R/'pangram_web/segments_mapped.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')

E=html.escape
rows=''.join(f'<tr><th>{E(x["episode"])}</th><td>{x["AI_labeled_percent_recomputed"]:.1f}%</td><td>{x["AI_labeled_word_units"]} / {x["surface_word_units"]}</td><td>{s["sentence_length_words"]["mean"]:.1f}</td><td>{sum(s["internal_circumflex_tokens"]["î"].values())} / {sum(s["internal_circumflex_tokens"]["â"].values())}</td></tr>' for x,s in zip(episodes,m['sections']))
starts=[0]+[body.index(x) for x in ['Se zice că Thom Yorke','Cînd Nick Cave a lansat','În ’81, când Kraftwerk']]+[len(body)]
heatmaps=[]
for i,episode in enumerate(episodes):
 start,end=starts[i],starts[i+1];cursor=start;pieces=[]
 for s in r['segments']:
  a=max(start,s['start_original_char']);b=min(end,s['end_original_char'])
  if b<=a:continue
  pieces.append(E(body[cursor:a]));label=s['label'];probs=s['class_percentages_displayed']
  title=f'Segment {s["i"]}: {label}; {s["confidence_label_displayed"]} confidence. Displayed class percentages: AI {probs["AI"]}%, AI-assisted {probs["AI-assisted"]}%, Human {probs["Human"]}%.'
  pieces.append(f'<mark class="{label.lower()}" tabindex="0" title="{E(title,quote=True)}" aria-label="{E(title,quote=True)}">{E(body[a:b])}</mark>');cursor=b
 pieces.append(E(body[cursor:end]))
 heatmaps.append(f'<details open><summary>{E(episode["episode"])} <span>{episode["AI_labeled_percent_recomputed"]:.1f}% AI-labeled word coverage</span></summary><div class="story">'+''.join(pieces)+'</div></details>')
rubric_rows=[]
for metric in v['metrics']:
 score='Not applicable' if metric['score'] is None else str(metric['score'])+' / 4'
 evidence='<br>'.join('<q>'+E(x['quote'])+'</q> '+E(x['reason']) for x in metric['evidence']) or ('No issue observed in the transferable narrative criterion.' if metric['score']==0 else 'Academic abstract criterion does not transfer reliably to this literary text.')
 rubric_rows.append(f'<tr><th>{E(metric["label"])}</th><td>{score}</td><td>{E(metric["kind"].replace("_"," "))}</td><td>{evidence}</td></tr>')
segment_rows=''.join(f'<tr><td>{s["i"]}</td><td>{s["label"]}</td><td>{s["confidence_label_displayed"]}</td><td>{s["unicode_word_units"]}</td><td>{E(s["text"][:150])}'+('…' if len(s['text'])>150 else '')+'</td></tr>' for s in r['segments'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sociu and Gemini: detector and stylometry analysis</title><style>
:root{color-scheme:light;--ink:#162f2b;--muted:#52635f;--line:#d8dfda;--paper:#fbfaf5;--ai:#ffe1ce;--human:#dff1e4}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 Georgia,serif}main{max-width:1100px;margin:auto;padding:52px 30px 80px}h1{font-size:clamp(30px,4vw,46px);line-height:1.13;max-width:850px;margin:10px 0 20px}h2{font-size:25px;margin:42px 0 12px}h3{font-size:19px;margin-bottom:6px}.eyebrow,table,summary,.meta,.pill{font-family:system-ui,sans-serif}.eyebrow{letter-spacing:.1em;font-size:12px;font-weight:750;text-transform:uppercase;color:var(--muted)}.lede{font-size:21px;max-width:900px}.meta{font-size:13px;color:var(--muted)}.result{padding:20px 24px;border:1px solid var(--line);background:#fff;border-left:5px solid #e66c31;margin:26px 0}.result strong{font-size:26px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.stat{padding:18px;background:#edf1eb;border-radius:8px}.stat strong{display:block;font:700 27px system-ui,sans-serif}.stat span{font:13px system-ui,sans-serif;color:var(--muted)}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0}th,td{border-bottom:1px solid var(--line);padding:11px 12px;text-align:left;vertical-align:top}thead{background:#eaf0e8}tbody th{font-weight:600}.scroll{overflow-x:auto}.note{padding:14px 18px;background:#edf1eb;font-size:14px}a{color:#176356}li{margin:8px 0}.legend{display:flex;gap:18px;font:13px system-ui,sans-serif;margin:20px 0}.pill{padding:3px 9px;border-radius:4px}.ai{background:var(--ai)}.human{background:var(--human)}details{margin:18px 0;border:1px solid var(--line);background:#fff}summary{padding:14px 18px;font-weight:650;cursor:pointer}summary span{font-size:12px;font-weight:450;color:var(--muted);margin-left:15px}.story{white-space:pre-wrap;padding:8px 22px 24px;font-size:18px;line-height:1.9}mark{color:inherit;padding:2px 0;box-decoration-break:clone;-webkit-box-decoration-break:clone}mark:focus{outline:2px solid #375b50}q{font-style:italic}code{font-size:12px;overflow-wrap:anywhere}footer{margin-top:48px;border-top:1px solid var(--line);padding-top:20px;font-size:13px;color:var(--muted)}@media(max-width:680px){main{padding:30px 16px}.grid{grid-template-columns:repeat(2,1fr)}.story{font-size:16px;padding:6px 14px 20px}summary span{display:block;margin-left:0}th,td{padding:9px 7px}}
</style><main><div class="eyebrow">Single-text case study · 3 November 2026</div><h1>Does the published text support Sociu’s Gemini claim?</h1><p class="lede">The completed Pangram web scan is consistent with AI involvement. Its strongest localized signal covers the Kraftwerk episode. The available evidence does not establish a particular generator, the actual drafting history, or whether the co-credit accurately describes that history.</p><p class="meta">Dan Sociu &amp; Gemini, <cite>La sud de Londra (fragment)</cite>, <cite>Steaua</cite> 10/2026, printed pp. 48–49; PDF pages 49–50.</p><div class="result"><strong>Mixed · 66% AI · 34% human</strong><br>Pangram 4.1, web interface, 3 November 2026 at 8:51 PM Hong Kong time. These are displayed detector classifications, not measured proportions of actual authorship.</div>'''
page+=f'''<div class="grid"><div class="stat"><strong>24</strong><span>captured detector segments</span></div><div class="stat"><strong>70</strong><span>heuristically segmented sentences</span></div><div class="stat"><strong>24.1</strong><span>mean words per sentence</span></div><div class="stat"><strong>2–68</strong><span>sentence length range</span></div></div><h2>Where the detector’s labels fall</h2><p>The table groups the existing whole-document labels by literary episode. It does not represent four new scans. Word units are Unicode word runs; their total of 1,753 matches the website’s displayed count. Of these, 1,164 fall inside AI-labeled segments.</p><div class="scroll"><table><thead><tr><th>Episode</th><th>AI-labeled coverage</th><th>AI / total word units</th><th>Mean sentence words</th><th>Internal î / â token counts</th></tr></thead><tbody>{rows}</tbody></table></div><p>There are 12 AI-labeled and 12 human-labeled segments, of very different lengths. No segment is labeled AI-assisted. The web output provides rounded class percentages and confidence categories; raw API fractions are unavailable. Short segments include the three-word <q>Era în ‚97.</q>, labeled AI with low confidence, and the two-word <q>Doar șoptea.</q>, labeled human with medium confidence. Such tiny spans offer little independent linguistic evidence.</p><h2>Stylometric patterns and their implications</h2><ol><li><strong>Repeated narrative machinery.</strong> All four episodes relocate the origin of an internationally familiar musical sound to an obscure Romanian encounter. They repeatedly convert a local noise, body, or setting into an explanation of a musician’s later work. This regularity is compatible with repeated expansion of a prompt, but also with a deliberately constrained literary sequence. It is a hypothesis about composition, not a validated AI marker.</li><li><strong>A clear orthographic seam.</strong> The first three episodes have 57 tokens containing internal î and three containing â. The Kraftwerk episode has zero internal-î tokens and 14 internal-â tokens. Comparable forms include <q>cînd</q> versus <q>când</q>, and <q>fîș</q> versus <q>fâș</q>. This suggests inconsistent normalization or separately handled material. Publication editing, copying, or human revision could produce the same pattern. Some â spellings in the first three episodes are a proper name or a quoted song title.</li><li><strong>Explicit explanatory endings.</strong> <q>În realitate</q> occurs twice; the Billie episode uses <q>De asta</q> and <q>Era exact</q>. The narration often explains the symbolic connection after dramatizing it. This may resemble model-generated explanatory closure, but it also carries the joke and the sequence’s aesthetic premise.</li><li><strong>Local detail and sensory accumulation.</strong> Geography, industrial brands, clothes, food, and bodily sensations give the text a consistent regional texture. Examples include <q>Singer și Ileana</q>, <q>țigări Assos</q>, and <q>grea, densă și apoasă</q>. These features can occur in a human author’s writing or in a detailed prompt and its output. Specificity does not independently establish human authorship.</li><li><strong>Sentence rhythm is variable.</strong> The sentence-length coefficient of variation is 0.549, with a mean of 24.1 and a standard deviation of 13.25 word tokens. There are six sentences of at most five words and one of 68 words. No three-word sentence opening repeats exactly. The evidence therefore does not support a strong claim of monotonous sentence rhythm in this text.</li></ol><p class="note">The spelling seam and the fully AI-labeled Kraftwerk episode coincide. This is a useful localization of the question, not evidence that the detector uses spelling as its decision rule. In the first three episodes, 56.3% of word units also fall in AI-labeled spans of this same scan.</p><h2>Our linguistic measurement</h2><p>The established prose-metrics functions supply the word tokenizer, bidirectional MTLD, percentiles, and coefficients of variation. The sentence boundary heuristic was extended to recognize Romanian uppercase letters; the earlier ASCII-only rule found 62 sentences and missed eight boundaries. The revised count is 70. There are 1,690 word tokens, 866 lowercase surface types, a type-token ratio of 0.512, and MTLD of 167.9. These are descriptive values without a matched reference corpus; they are not human-versus-AI thresholds.</p><p>English readability indices and English hedge, booster, and first-person dictionaries were excluded. No Romanian part-of-speech or dependency parser was run. The 20-item writing rubric was retained in its original order, with seven academic-only checks marked not applicable. Thirteen transferable judgments were completed before the detector result was viewed. This is one model assessment, aware of the provenance claim, rather than an independently blinded panel.</p><details><summary>Evidence-backed rubric results</summary><div class="scroll"><table><thead><tr><th>Metric</th><th>Score</th><th>Kind</th><th>Evidence and scope</th></tr></thead><tbody>{''.join(rubric_rows)}</tbody></table></div></details><h2>Captured Pangram highlights</h2><p>Below is a local reconstruction from the completed web interface’s accessibility labels. Every segment was matched to the exact frozen body after whitespace normalization, with complete coverage and no extra text. Hover over or focus a highlight to read its segment number, confidence category, and displayed class percentages.</p><div class="legend"><span class="pill ai">AI-labeled</span><span class="pill human">Human-labeled</span></div>{''.join(heatmaps)}<details><summary>All 24 segment labels</summary><div class="scroll"><table><thead><tr><th>Segment</th><th>Label</th><th>Confidence</th><th>Word units</th><th>Opening</th></tr></thead><tbody>{segment_rows}</tbody></table></div></details><h2>What this says about the claim</h2><p>The disclosed collaboration is plausible and receives a positive detector signal. The repeated episode structure and the final episode’s spelling discontinuity are concrete patterns worth investigating. They do not establish that Gemini generated the whole piece, or identify which passages Sociu wrote or edited. Human-labeled spans are not authenticated human writing, and AI-labeled spans are not generation logs.</p><p>Actual drafts or generation records would provide stronger evidence. A separate attribution study would require authenticated Sociu prose and matched Romanian fiction from candidate models, controlling for genre, topic, length, and spelling. No likelihood ratio, authorship probability, or author-distance score is justified by this single text.</p><h2>Input and reproducibility</h2><p>The detector received the Romanian body only, without the title, author name, or Gemini credit. Extraction restored column order and printed paragraphs, joined five line-end word breaks, and removed running furniture and the terminal printer ornament. Original spelling and punctuation were preserved. The text has 1,693 whitespace words; the website’s tokenizer displays 1,753 words. The successful result comes from the requested web interface. The API attempt returned HTTP 402 and was not repeated.</p><ul><li><a href="sociu_body_ro.txt">Exact submitted body</a></li><li><a href="extraction_manifest.json">Extraction record and checksums</a></li><li><a href="stylometry.json">Full linguistic measurements</a></li><li><a href="pangram_web/result_summary.json">Detector result metadata</a> and <a href="pangram_web/segments_mapped.json">all segment observations</a></li><li><a href="protocol.json">Frozen measurement protocol</a> and <a href="web_protocol_addendum.json">web-interface addendum</a></li><li><a href="rubric_validation.json">Exact-quote validation</a></li><li><a href="analyze_stylometry.py">Reproducible linguistic analysis script</a></li></ul><footer><p>Scope and language support were checked against <a href="https://www.pangram.com/research/model-card/pangram-4-1">Pangram’s 4.1 model card</a>, which lists Romanian and recommends prose samples of at least 50 words. This report does not transfer the vendor’s aggregate accuracy claims to this literary case.</p><p>Measurement basis: Brilliant Humanizer writing-audit rubric v0.2.0 and the established academic-unslop prose-metrics implementation. These measures were developed for other genres and samples. They do not establish a detector’s causal internals.</p><p>Frozen input SHA-256: <code>{m['source_text_sha256']}</code></p></footer></main></html>'''
(R/'analysis_report.html').write_text(page)
