from html.parser import HTMLParser
class Stories(HTMLParser):
 def __init__(self):super().__init__();self.in_story=False;self.depth=0;self.text=[]
 def handle_starttag(self,tag,attrs):
  if tag=='div' and dict(attrs).get('class')=='story':self.in_story=True;self.depth=1
  elif self.in_story and tag=='div':self.depth+=1
 def handle_endtag(self,tag):
  if self.in_story and tag=='div':
   self.depth-=1
   if self.depth==0:self.in_story=False
 def handle_data(self,data):
  if self.in_story:self.text.append(data)
p=Stories();p.feed(page)
assert ''.join(p.text)==body
assert not v['invalid_evidence'] and v['assessed_metrics']==13
assert len(episodes)==4 and sum(e['surface_word_units'] for e in episodes)==1753
